     5	public final class NaiveSearchEngine implements SearchEngine {
     6	
     7	    @Override
     8	    public SearchResult search(SearchRequest request) {
     9	        Objects.requireNonNull(request, "request must not be null");
    10	
    11	        if (request.patternIsLongerThanText()) {
    12	            return new SearchResult(request, List.of());
    13	        }
    14	
    15	        List<Integer> matchIndexes = new ArrayList<>();
    16	        int patternLength = request.patternLength();
    17	
    18	        for (int startIndex = 0;
    19	                startIndex <= request.textLength() - patternLength;
    20	                startIndex++) {
    21	            if (matchesAt(request, startIndex, patternLength)) {
    22	                matchIndexes.add(startIndex);
    23	            }
    24	        }
    25	
    26	        return new SearchResult(request, matchIndexes);
    27	    }
    28	
    29	    private boolean matchesAt(SearchRequest request, int startIndex, int patternLength) {
    30	        for (int offset = 0; offset < patternLength; offset++) {
    31	            if (request.text().charAt(startIndex + offset)
    32	                    != request.pattern().charAt(offset)) {
    33	                return false;
    34	            }
    35	        }
    36	
    37	        return true;
    38	    }
    39	}
